// ---------------------------------------------------------------------------------------------
// Errors

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum Kind {
    NotInstalled,
    PathInvalid,
    StartFailed,
    Disconnected,
    Protocol,
    Timeout,
    Cancelled,
    AuthRequired,
    AuthUnsupported,
    UsageLimit,
    Network,
    RequestFailed,
    ConfigInvalid,
    ProviderUnsupported,
    PolicyUnsupported,
    InputInvalid,
    RequestTooLarge,
    ResponseTooLarge,
    Empty,
    TurnFailed,
    LoginFailed,
    Busy,
    Blocked,
}

/// A user-safe failure: the message never contains paths, URLs or raw payloads.
#[derive(Clone, Debug)]
struct CodexError {
    kind: Kind,
    message: String,
}

impl CodexError {
    fn new(kind: Kind, message: impl Into<String>) -> Self {
        Self { kind, message: message.into() }
    }
}

fn err(kind: Kind) -> CodexError {
    let message = match kind {
        Kind::NotInstalled => "Install the Codex CLI, or set CODEX_PATH to its executable.",
        Kind::PathInvalid => "CODEX_PATH must be the absolute path of the Codex executable or its official launcher.",
        Kind::StartFailed => "Codex could not start. Verify the official CLI installation and configuration.",
        Kind::Disconnected => "Codex disconnected. Try again to reconnect.",
        Kind::Protocol => "Codex returned an invalid response.",
        Kind::Timeout => "Codex did not respond in time. Please retry.",
        Kind::Cancelled => "Cancelled.",
        Kind::AuthRequired => "Sign in to Codex with your ChatGPT account in Settings.",
        Kind::AuthUnsupported => "This assistant requires ChatGPT sign-in. API-key and Amazon Bedrock accounts are not supported.",
        Kind::UsageLimit => "Your Codex usage limit has been reached. Check your plan and try again when usage resets.",
        Kind::Network => "The connection to Codex was interrupted. Check your network and retry.",
        Kind::RequestFailed => "Codex could not complete the request. Check your sign-in, model and CLI configuration.",
        Kind::ConfigInvalid => "The Codex configuration cannot be safely restricted.",
        Kind::ProviderUnsupported => "This assistant requires the official OpenAI provider. Remove custom provider or endpoint overrides from your Codex configuration.",
        Kind::PolicyUnsupported => "Codex did not apply the required restrictions.",
        Kind::InputInvalid => "Provide a question or a screenshot.",
        Kind::RequestTooLarge => "The request is too large to send to Codex.",
        Kind::ResponseTooLarge => "The answer exceeded the response limit. Ask a more focused question.",
        Kind::Empty => "Codex finished without an answer. Please retry.",
        Kind::TurnFailed => "Codex could not finish this response. Please try again.",
        Kind::LoginFailed => "Codex sign-in failed. Please try again.",
        Kind::Busy => "Too many Codex requests are pending.",
        Kind::Blocked => "This Codex operation is not available in the assistant.",
    };
    CodexError::new(kind, message)
}

/// `rate.?limit` without a regex engine.
fn mentions_rate_limit(lower: &str) -> bool {
    lower.match_indices("rate").any(|(index, _)| {
        let rest = &lower[index + 4..];
        rest.starts_with("limit") || rest.chars().next().is_some_and(|c| rest[c.len_utf8()..].starts_with("limit"))
    })
}

/// Maps a JSON-RPC error object to a short user-safe error (`rpcError` in client.js).
fn rpc_error(payload: &Value) -> CodexError {
    let code = payload.get("code").and_then(Value::as_i64);
    let message = payload.get("message").and_then(Value::as_str).unwrap_or("").to_lowercase();
    if code == Some(429) || mentions_rate_limit(&message) || ["usage limit", "quota", "credits"].iter().any(|word| message.contains(word)) {
        err(Kind::UsageLimit)
    } else if matches!(code, Some(401 | 403))
        || ["unauthorized", "unauthorised", "not authenticated", "sign in", "authentication"].iter().any(|word| message.contains(word))
    {
        err(Kind::AuthRequired)
    } else {
        err(Kind::RequestFailed)
    }
}

/// Maps a finished non-`completed` turn to a user-safe error (`turnFailure` in response-stream.js).
fn turn_failure(turn: &Value) -> CodexError {
    if turn.get("status").and_then(Value::as_str) == Some("interrupted") {
        return err(Kind::Cancelled);
    }
    let error = turn.get("error").unwrap_or(&Value::Null);
    let detail = match error.get("codexErrorInfo") {
        Some(Value::String(text)) => text.clone(),
        Some(other) if !other.is_null() => other.to_string(),
        _ => String::new(),
    };
    let message = error.get("message").and_then(Value::as_str).unwrap_or("");
    let text = format!("{detail} {message}").to_lowercase();
    let any = |words: &[&str]| words.iter().any(|word| text.contains(word));
    if any(&["usagelimit", "quota", "429"]) || mentions_rate_limit(&text) {
        err(Kind::UsageLimit)
    } else if any(&["unauthorized", "authentication", "401", "403"]) {
        err(Kind::AuthRequired)
    } else if any(&["connection", "network", "streamdisconnected", "httpconnection", "timeout", "offline"]) {
        err(Kind::Network)
    } else {
        err(Kind::TurnFailed)
    }
}

// ---------------------------------------------------------------------------------------------
// JSON-RPC framing

/// Splits a byte stream into newline-terminated lines, bounding the buffered line size.
#[derive(Default)]
struct LineBuffer {
    buffer: Vec<u8>,
}

impl LineBuffer {
    fn feed(&mut self, mut chunk: &[u8], max: usize) -> Result<Vec<Vec<u8>>, CodexError> {
        let mut lines = Vec::new();
        while let Some(newline) = chunk.iter().position(|&byte| byte == b'\n') {
            if self.buffer.len() + newline > max {
                return Err(err(Kind::Protocol));
            }
            self.buffer.extend_from_slice(&chunk[..newline]);
            lines.push(std::mem::take(&mut self.buffer));
            chunk = &chunk[newline + 1..];
        }
        if self.buffer.len() + chunk.len() > max {
            return Err(err(Kind::Protocol));
        }
        self.buffer.extend_from_slice(chunk);
        Ok(lines)
    }
}

#[derive(Debug)]
enum Incoming {
    Response { id: Value, outcome: Result<Value, Value> },
    Request { id: Value, method: String },
    Notification { method: String, params: Value },
}

fn is_request_id(value: &Value) -> bool {
    value.is_string() || value.is_i64() || value.is_u64()
}

/// Strict UTF-8 + JSON envelope validation. `Ok(None)` for blank lines.
fn parse_line(line: &[u8]) -> Result<Option<Incoming>, CodexError> {
    let text = std::str::from_utf8(line).map_err(|_| err(Kind::Protocol))?.trim();
    if text.is_empty() {
        return Ok(None);
    }
    let Value::Object(mut message) = serde_json::from_str::<Value>(text).map_err(|_| err(Kind::Protocol))? else {
        return Err(err(Kind::Protocol));
    };
    if let Some(Value::String(method)) = message.remove("method") {
        return match message.remove("id") {
            Some(id) if is_request_id(&id) => Ok(Some(Incoming::Request { id, method })),
            Some(_) => Err(err(Kind::Protocol)),
            None => {
                let params = message.remove("params").filter(|params| !params.is_null()).unwrap_or_else(|| json!({}));
                Ok(Some(Incoming::Notification { method, params }))
            }
        };
    }
    let id = message.remove("id").filter(is_request_id).ok_or_else(|| err(Kind::Protocol))?;
    match (message.remove("result"), message.remove("error")) {
        (Some(result), None) => Ok(Some(Incoming::Response { id, outcome: Ok(result) })),
        (None, Some(error)) => Ok(Some(Incoming::Response { id, outcome: Err(error) })),
        _ => Err(err(Kind::Protocol)),
    }
}

fn encode_line(message: &Value) -> Result<Vec<u8>, CodexError> {
    let mut bytes = serde_json::to_vec(message).map_err(|_| err(Kind::RequestTooLarge))?;
    bytes.push(b'\n');
    if bytes.len() > MAX_WRITE_BYTES {
        return Err(err(Kind::RequestTooLarge));
    }
    Ok(bytes)
}

/// The reply to a server→client request: every approval, tool call or prompt is declined.
fn denial(id: &Value, method: &str) -> Value {
    let disabled = "Tools are disabled in this assistant.";
    let result = match method {
        "item/commandExecution/requestApproval" | "item/fileChange/requestApproval" => json!({ "decision": "decline" }),
        "applyPatchApproval" | "execCommandApproval" => json!({ "decision": { "denied": { "rejection": disabled } } }),
        "item/permissions/requestApproval" => json!({ "permissions": {}, "scope": "turn", "strictAutoReview": true }),
        "item/tool/requestUserInput" => json!({ "answers": {} }),
        "item/tool/call" => json!({ "success": false, "contentItems": [{ "type": "inputText", "text": disabled }] }),
        "mcpServer/elicitation/request" => json!({ "action": "decline", "content": null, "_meta": null }),
        _ => {
            return json!({ "id": id, "error": { "code": -32601, "message": "This client does not support server-initiated requests." } });
        }
    };
    json!({ "id": id, "result": result })
}

// ---------------------------------------------------------------------------------------------
// Launch and thread policy

fn restricted_config() -> Map<String, Value> {
    let mut config = Map::new();
    for (key, value) in [
        ("model_provider", json!("openai")),
        ("approval_policy", json!("never")),
        ("sandbox_mode", json!("read-only")),
        ("web_search", json!("disabled")),
        ("project_doc_max_bytes", json!(0)),
        ("project_doc_fallback_filenames", json!([])),
        ("developer_instructions", json!("")),
        ("notify", json!([])),
        ("history.persistence", json!("none")),
        ("analytics.enabled", json!(false)),
        ("shell_environment_policy.inherit", json!("none")),
        ("features.skip_host_skill_discovery", json!(true)),
    ] {
        config.insert(key.to_string(), value);
    }
    for feature in DISABLED_FEATURES {
        config.insert(format!("features.{feature}"), json!(false));
    }
    config
}

/// argv entries, never shell text. JSON primitives and empty arrays are also TOML literals.
fn launch_arguments() -> Vec<String> {
    let mut args = vec!["app-server".to_string(), "--stdio".to_string()];
    for (key, value) in restricted_config() {
        args.push("-c".into());
        args.push(format!("{key}={value}"));
    }
    args
}

/// Keeps only allowlisted variables (case-insensitively, first occurrence wins).
fn sanitize_environment(source: impl IntoIterator<Item = (OsString, OsString)>) -> Vec<(OsString, OsString)> {
    let mut seen = Vec::<String>::new();
    let mut result = Vec::new();
    for (name, value) in source {
        let Some(upper) = name.to_str().map(str::to_ascii_uppercase) else { continue };
        let Some(text) = value.to_str() else { continue };
        if !ENV_ALLOWLIST.contains(&upper.as_str()) || seen.contains(&upper) || text.contains('\0') {
            continue;
        }
        seen.push(upper);
        result.push((name, value));
    }
    result
}

fn is_official_chatgpt_base(url: &str) -> bool {
    let Some(rest) = url.strip_prefix("https://chatgpt.com") else { return false };
    if rest.contains(['?', '#', '@', '\\']) || !(rest.is_empty() || rest.starts_with('/')) {
        return false;
    }
    matches!(rest.trim_end_matches('/'), "/backend-api" | "/backend-api/codex")
}

/// Builds the per-thread config from `config/read` (`threadConfigFromEffective` in policy.js).
/// The effective configuration may contain secrets: it is inspected here and never retained.
fn thread_config_from_effective(config: Option<&Value>) -> Result<Map<String, Value>, CodexError> {
    let Some(Value::Object(config)) = config else { return Err(err(Kind::ConfigInvalid)) };
    let present = |value: Option<&Value>| value.is_some_and(|value| !value.is_null());
    if let Some(provider) = config.get("model_provider").filter(|value| !value.is_null())
        && provider.as_str().is_none_or(|provider| !provider.is_empty() && provider != "openai")
    {
        return Err(err(Kind::ProviderUnsupported));
    }
    if let Some(base) = config.get("chatgpt_base_url").filter(|value| !value.is_null())
        && !base.as_str().is_some_and(is_official_chatgpt_base)
    {
        return Err(err(Kind::ProviderUnsupported));
    }
    if let Some(provider) = config.get("model_providers").and_then(|providers| providers.get("openai")) {
        let overridden = ["base_url", "auth", "env_key", "experimental_bearer_token", "http_headers", "env_http_headers", "query_params"]
            .iter()
            .any(|key| present(provider.get(*key)));
        let wire = provider.get("wire_api").filter(|value| !value.is_null());
        if overridden || provider.get("requires_openai_auth") == Some(&Value::Bool(false)) || wire.is_some_and(|wire| wire != "responses") {
            return Err(err(Kind::ProviderUnsupported));
        }
    }
    let mut result = restricted_config();
    match config.get("mcp_servers") {
        None | Some(Value::Null) => {}
        Some(Value::Object(servers)) if servers.len() <= 256 => {
            // Empty tables can merge with inherited entries; disable every observed server.
            for name in servers.keys() {
                if name.is_empty() || name.len() > 256 || !name.chars().all(|c| c.is_ascii_alphanumeric() || c == '_' || c == '-') {
                    return Err(err(Kind::ConfigInvalid));
                }
                result.insert(format!("mcp_servers.{name}.enabled"), json!(false));
                result.insert(format!("mcp_servers.{name}.required"), json!(false));
            }
        }
        Some(_) => return Err(err(Kind::ConfigInvalid)),
    }
    if let Some(Value::Array(skills)) = config.get("skills").and_then(|skills| skills.get("config")) {
        let disabled: Vec<Value> = skills
            .iter()
            .filter_map(|skill| skill.get("path").and_then(Value::as_str))
            .map(|path| json!({ "path": path, "enabled": false }))
            .collect();
        result.insert("skills.config".into(), Value::Array(disabled));
    }
    Ok(result)
}

// ---------------------------------------------------------------------------------------------
// Instruction-source policy

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum Family {
    Windows,
    Unix,
    Unknown,
}

/// Normalizes a protocol path for comparison without touching the filesystem.
/// Returns `None` for relative, device-namespace, traversal or otherwise ambiguous paths.
fn native_absolute(value: &str, family: Family, directory: bool) -> Option<String> {
    if value.is_empty() || value.chars().count() > 32_767 || value.chars().any(|c| (c as u32) < 32 || c as u32 == 127) {
        return None;
    }
    match family {
        Family::Unknown => None,
        Family::Unix => {
            if !value.starts_with('/') || value.starts_with("//") || (!directory && value.ends_with('/')) {
                return None;
            }
            let parts: Vec<&str> = value.split('/').filter(|part| !part.is_empty()).collect();
            if parts.iter().any(|part| *part == "." || *part == "..") {
                return None;
            }
            Some(format!("/{}", parts.join("/")))
        }
        Family::Windows => {
            let mut native = value.replace('/', "\\");
            // Rust can report verbatim drive or UNC paths. Device namespaces are never accepted.
            if native.get(..8).is_some_and(|prefix| prefix.eq_ignore_ascii_case("\\\\?\\UNC\\")) {
                native = format!("\\\\{}", &native[8..]);
            } else if native.starts_with("\\\\?\\") && is_drive_root(&native[4..]) {
                native = native[4..].to_string();
            }
            let drive = is_drive_root(&native);
            let unc = !drive && is_unc(&native);
            if (!drive && !unc) || (!directory && native.ends_with('\\')) {
                return None;
            }
            let body = if drive { &native[3..] } else { &native[2..] };
            let invalid = |part: &&str| {
                *part == "." || *part == ".." || part.ends_with(' ') || part.ends_with('.') || part.contains(['<', '>', ':', '"', '|', '?', '*'])
            };
            if body.split('\\').any(|part| invalid(&part)) {
                return None;
            }
            let parts: Vec<&str> = body.split('\\').filter(|part| !part.is_empty()).collect();
            let normalized = if drive {
                format!("{}\\{}", &native[..2], parts.join("\\"))
            } else {
                format!("\\\\{}", parts.join("\\"))
            };
            Some(normalized.to_lowercase())
        }
    }
}

fn is_drive_root(path: &str) -> bool {
    let bytes = path.as_bytes();
    bytes.len() >= 3 && bytes[0].is_ascii_alphabetic() && bytes[1] == b':' && bytes[2] == b'\\'
}

/// `^\\server\share(\|$)`
fn is_unc(path: &str) -> bool {
    let Some(rest) = path.strip_prefix("\\\\") else { return false };
    let mut parts = rest.splitn(3, '\\');
    matches!((parts.next(), parts.next()), (Some(server), Some(share)) if !server.is_empty() && !share.is_empty())
}

/// Accepts at most one standard global instruction file under the reported Codex home and
/// never a project or arbitrary path. Private paths stay inside this value.
#[derive(Debug)]
struct InstructionPolicy {
    family: Family,
    allowed: Vec<String>,
}

impl InstructionPolicy {
    fn from_initialize(initialized: &Value) -> Self {
        let family = match initialized.get("platformFamily").and_then(Value::as_str) {
            Some("windows") => Family::Windows,
            Some("unix") => Family::Unix,
            _ => Family::Unknown,
        };
        let home = initialized.get("codexHome").and_then(Value::as_str).and_then(|home| native_absolute(home, family, true));
        let separator = if family == Family::Windows { '\\' } else { '/' };
        let allowed = home
            .map(|home| {
                GLOBAL_INSTRUCTION_NAMES
                    .iter()
                    .filter_map(|name| {
                        let joined = if home.ends_with(separator) { format!("{home}{name}") } else { format!("{home}{separator}{name}") };
                        native_absolute(&joined, family, false)
                    })
                    .collect()
            })
            .unwrap_or_default();
        Self { family, allowed }
    }

    fn allows(&self, sources: Option<&Value>) -> bool {
        let Some(Value::Array(sources)) = sources else { return false };
        match sources.as_slice() {
            [] => true,
            [Value::String(source)] => native_absolute(source, self.family, false).is_some_and(|source| self.allowed.contains(&source)),
            _ => false,
        }
    }
}

/// Confirms that `thread/start` applied every restriction; returns the thread id.
fn validate_thread_start(response: &Value, cwd: &str, policy: Option<&InstructionPolicy>) -> Result<String, CodexError> {
    let thread_id = response
        .get("thread")
        .and_then(|thread| thread.get("id"))
        .and_then(Value::as_str)
        .filter(|id| !id.is_empty() && id.len() <= 1024)
        .ok_or_else(|| err(Kind::Protocol))?;
    let family = policy.map_or(Family::Unknown, |policy| policy.family);
    let reported_cwd = response.get("cwd").and_then(Value::as_str);
    let same_cwd = reported_cwd.is_some_and(|reported| {
        reported == cwd
            || (family == Family::Windows
                && native_absolute(reported, family, true).is_some_and(|reported| Some(reported) == native_absolute(cwd, family, true)))
    });
    let sandbox = response.get("sandbox");
    let mut mismatches = Vec::new();
    if response.get("modelProvider").and_then(Value::as_str) != Some("openai") {
        mismatches.push("provider");
    }
    if !same_cwd {
        mismatches.push("working directory");
    }
    if response.get("approvalPolicy").and_then(Value::as_str) != Some("never") {
        mismatches.push("approvals");
    }
    if sandbox.and_then(|sandbox| sandbox.get("type")).and_then(Value::as_str) != Some("readOnly") {
        mismatches.push("sandbox");
    }
    if sandbox.and_then(|sandbox| sandbox.get("networkAccess")) != Some(&Value::Bool(false)) {
        mismatches.push("network");
    }
    if !policy.is_some_and(|policy| policy.allows(response.get("instructionSources"))) {
        mismatches.push("instruction sources");
    }
    if mismatches.is_empty() {
        Ok(thread_id.to_string())
    } else {
        Err(CodexError::new(Kind::PolicyUnsupported, format!("Codex did not apply the required restrictions: {}.", mismatches.join(", "))))
    }
}

// ---------------------------------------------------------------------------------------------
// Turn streaming

/// Normal assistant messages only. Reasoning and tool events never enter this accumulator.
#[derive(Default)]
struct ResponseText {
    /// (item id, text, char count) in arrival order.
    items: Vec<(String, String, usize)>,
    chars: usize,
}

impl ResponseText {
    fn text(&self) -> String {
        self.items.iter().map(|(_, text, _)| text.as_str()).collect::<Vec<_>>().join("\n\n")
    }

    /// Applies one event and returns the text to append to what was already shown ("" when a
    /// completion rewrote earlier text; the final answer then replaces the streamed one).
    fn consume(&mut self, method: &str, params: &Value) -> Result<String, CodexError> {
        let invalid = || err(Kind::Protocol);
        let (id, value, appended) = match method {
            "item/agentMessage/delta" => {
                let delta = params.get("delta").and_then(Value::as_str).ok_or_else(invalid)?;
                (params.get("itemId").and_then(Value::as_str), delta, true)
            }
            "item/completed" if params.get("item").and_then(|item| item.get("type")).and_then(Value::as_str) == Some("agentMessage") => {
                let item = &params["item"];
                (item.get("id").and_then(Value::as_str), item.get("text").and_then(Value::as_str).ok_or_else(invalid)?, false)
            }
            _ => return Ok(String::new()),
        };
        let id = id.filter(|id| !id.is_empty() && id.len() <= 1024).ok_or_else(invalid)?;
        let position = self.items.iter().position(|(item, _, _)| item == id);
        let old_chars = position.map_or(0, |index| self.items[index].2);
        let value_chars = value.chars().count();
        let new_item_chars = if appended { old_chars + value_chars } else { value_chars };
        let total = self.chars - old_chars + new_item_chars;
        if total > MAX_RESPONSE_CHARS || (position.is_none() && self.items.len() >= MAX_RESPONSE_ITEMS) {
            return Err(err(Kind::ResponseTooLarge));
        }
        // Fast path: streaming into the last item appends exactly the delta.
        if appended && position.is_some_and(|index| index + 1 == self.items.len()) {
            let last = self.items.last_mut().expect("position checked");
            last.1.push_str(value);
            last.2 = new_item_chars;
            self.chars = total;
            return Ok(value.to_string());
        }
        let before = self.text();
        match position {
            Some(index) => {
                let item = &mut self.items[index];
                if appended { item.1.push_str(value) } else { item.1 = value.to_string() }
                item.2 = new_item_chars;
            }
            None => self.items.push((id.to_string(), value.to_string(), new_item_chars)),
        }
        self.chars = total;
        let after = self.text();
        Ok(after.strip_prefix(before.as_str()).map(str::to_string).unwrap_or_default())
    }
}

#[derive(Debug, PartialEq)]
enum TurnStep {
    Continue,
    Done(String),
}

/// Handles notifications arriving both before and after `turn/start` acknowledges its turn id,
/// rejecting events from other threads and stale turns.
struct TurnTracker {
    thread_id: String,
    turn_id: Option<String>,
    early: Vec<(String, Value)>,
    early_chars: usize,
    output: ResponseText,
    finished: bool,
}

impl TurnTracker {
    fn new(thread_id: &str) -> Self {
        Self { thread_id: thread_id.to_string(), turn_id: None, early: Vec::new(), early_chars: 0, output: ResponseText::default(), finished: false }
    }

    fn on_notification(&mut self, method: &str, params: &Value, emit: &mut dyn FnMut(&str)) -> Result<TurnStep, CodexError> {
        if self.finished
            || !matches!(method, "item/agentMessage/delta" | "item/completed" | "turn/completed")
            || params.get("threadId").and_then(Value::as_str) != Some(self.thread_id.as_str())
        {
            return Ok(TurnStep::Continue);
        }
        if method == "item/completed" && params.get("item").and_then(|item| item.get("type")).and_then(Value::as_str) != Some("agentMessage") {
            return Ok(TurnStep::Continue);
        }
        if self.turn_id.is_none() {
            let size = params.get("delta").or_else(|| params.get("item").and_then(|item| item.get("text"))).and_then(Value::as_str).map_or(0, |text| text.chars().count());
            self.early_chars += size;
            if self.early.len() >= MAX_EARLY_EVENTS || self.early_chars > MAX_RESPONSE_CHARS {
                return Err(err(Kind::Protocol));
            }
            self.early.push((method.to_string(), params.clone()));
            return Ok(TurnStep::Continue);
        }
        self.consume(method, params, emit)
    }

    fn on_started(&mut self, result: &Value, emit: &mut dyn FnMut(&str)) -> Result<TurnStep, CodexError> {
        let turn = result.get("turn").ok_or_else(|| err(Kind::Protocol))?;
        let id = turn.get("id").and_then(Value::as_str).filter(|id| !id.is_empty()).ok_or_else(|| err(Kind::Protocol))?;
        self.turn_id = Some(id.to_string());
        for (method, params) in std::mem::take(&mut self.early) {
            if let TurnStep::Done(text) = self.consume(&method, &params, emit)? {
                return Ok(TurnStep::Done(text));
            }
        }
        if matches!(turn.get("status").and_then(Value::as_str), Some("completed" | "failed" | "interrupted")) {
            return self.consume("turn/completed", &json!({ "threadId": self.thread_id, "turn": turn }), emit);
        }
        Ok(TurnStep::Continue)
    }

    fn consume(&mut self, method: &str, params: &Value, emit: &mut dyn FnMut(&str)) -> Result<TurnStep, CodexError> {
        let event_turn = params.get("turnId").or_else(|| params.get("turn").and_then(|turn| turn.get("id"))).and_then(Value::as_str);
        if event_turn != self.turn_id.as_deref() {
            return Ok(TurnStep::Continue);
        }
        if method == "turn/completed" {
            self.finished = true;
            let turn = &params["turn"];
            if turn.get("status").and_then(Value::as_str) != Some("completed") {
                return Err(turn_failure(turn));
            }
            for item in turn.get("items").and_then(Value::as_array).into_iter().flatten() {
                self.output.consume("item/completed", &json!({ "item": item }))?;
            }
            let text = self.output.text();
            if text.trim().is_empty() {
                return Err(err(Kind::Empty));
            }
            return Ok(TurnStep::Done(text));
        }
        let delta = self.output.consume(method, params)?;
        if !delta.is_empty() {
            emit(&delta);
        }
        Ok(TurnStep::Continue)
    }
}

fn text_item(text: String) -> Value {
    json!({ "type": "text", "text": text, "text_elements": [] })
}

fn joined_text(message: &Message, separator: &str) -> String {
    message
        .parts
        .iter()
        .filter_map(|part| match part {
            Part::Text(text) if !text.trim().is_empty() => Some(text.trim()),
            _ => None,
        })
        .collect::<Vec<_>>()
        .join(separator)
}

/// Folds a stateless conversation into one turn's input: earlier messages as a text transcript,
/// then the current user message's text and its JPEG screenshots as data URLs.
fn fold_input(messages: &[Message]) -> Result<Vec<Value>, CodexError> {
    let Some((current, history)) = messages.split_last() else { return Err(err(Kind::InputInvalid)) };
    if current.role != Role::User {
        return Err(err(Kind::InputInvalid));
    }
    let mut items = Vec::new();
    let transcript: Vec<String> = history
        .iter()
        .filter_map(|message| {
            let text = joined_text(message, "\n");
            let label = match message.role {
                Role::User => "User",
                Role::Assistant => "Assistant",
            };
            (!text.is_empty()).then(|| format!("{label}: {text}"))
        })
        .collect();
    if !transcript.is_empty() {
        items.push(text_item(format!("Conversation so far:\n\n{}", transcript.join("\n\n"))));
    }
    let text = joined_text(current, "\n\n");
    let has_text = !text.is_empty();
    if has_text {
        items.push(text_item(text));
    }
    let mut images = 0;
    for part in &current.parts {
        if let Part::Jpeg(bytes) = part
            && !bytes.is_empty()
        {
            images += 1;
            let data = base64::engine::general_purpose::STANDARD.encode(bytes);
            items.push(json!({ "type": "image", "url": format!("data:image/jpeg;base64,{data}") }));
        }
    }
    if !has_text && images == 0 {
        return Err(err(Kind::InputInvalid));
    }
    if items.len() > MAX_INPUT_ITEMS
        || items.iter().any(|item| item.get("text").and_then(Value::as_str).is_some_and(|text| text.len() > MAX_TEXT_INPUT))
    {
        return Err(err(Kind::RequestTooLarge));
    }
    Ok(items)
}

fn valid_model(model: &str) -> bool {
    !model.is_empty() && model.len() <= 200 && model.chars().all(|c| c.is_ascii_graphic())
}

/// The sign-in page must be on an official origin, without credentials, ports or odd characters.
fn valid_auth_url(url: &str) -> bool {
    url.len() <= 8192
        && url.bytes().all(|byte| byte.is_ascii_graphic() && !matches!(byte, b'"' | b'<' | b'>' | b'\\' | b'`' | b'{' | b'}' | b'|' | b'^'))
        && AUTH_ORIGINS.iter().any(|origin| {
            url.strip_prefix(origin).is_some_and(|rest| rest.is_empty() || rest.starts_with(['/', '?', '#']))
        })
}

// ---------------------------------------------------------------------------------------------
// Process and transport (injectable for tests)

trait Process: Send {
    fn kill(&mut self);
    fn wait(&mut self);
    /// Removes the owned working directory (non-recursively).
    fn cleanup(&mut self);
}

struct Spawned {
    writer: Box<dyn Write + Send>,
    reader: Box<dyn Read + Send>,
    process: Box<dyn Process>,
    cwd: String,
}

trait Launcher: Send + Sync {
    /// Locates the native executable without starting it.
    fn resolve(&self) -> Result<PathBuf, CodexError>;
    fn launch(&self) -> Result<Spawned, CodexError>;
    fn open_url(&self, url: &str) -> Result<(), CodexError>;
}

struct SystemLauncher;

struct ChildProcess {
    child: Child,
    cwd: PathBuf,
}

impl Process for ChildProcess {
    fn kill(&mut self) {
        let _ = self.child.kill();
    }
    fn wait(&mut self) {
        let _ = self.child.wait();
    }
    fn cleanup(&mut self) {
        // Remove only an empty owned directory; never recurse.
        let _ = std::fs::remove_dir(&self.cwd);
    }
}

fn create_workspace() -> Result<PathBuf, CodexError> {
    static COUNTER: AtomicU64 = AtomicU64::new(0);
    let base = std::env::temp_dir();
    for _ in 0..8 {
        let nanos = SystemTime::now().duration_since(UNIX_EPOCH).map_or(0, |time| time.subsec_nanos());
        let count = COUNTER.fetch_add(1, Ordering::Relaxed);
        let path = base.join(format!("cluelyrs-codex-{}-{nanos:08x}-{count}", std::process::id()));
        match std::fs::create_dir(&path) {
            Ok(()) => return Ok(path),
            Err(error) if error.kind() == ErrorKind::AlreadyExists => continue,
            Err(_) => break,
        }
    }
    Err(err(Kind::StartFailed))
}

fn is_launcher_script(path: &Path) -> bool {
    path.extension().and_then(|ext| ext.to_str()).is_some_and(|ext| ["cmd", "bat", "ps1"].iter().any(|bad| ext.eq_ignore_ascii_case(bad)))
}

/// Where the Codex CLI was found, or a user-safe reason it wasn't.
pub fn executable() -> Result<PathBuf, String> {
    SystemLauncher.resolve().map_err(|error| error.message)
}

/// Whether a file the user picked can be used as the Codex CLI, by the rules of the search.
pub fn check_location(path: &Path) -> Result<(), String> {
    located(path).map(drop).ok_or_else(|| "That isn't the Codex CLI.".to_string())
}

impl Launcher for SystemLauncher {
    fn resolve(&self) -> Result<PathBuf, CodexError> {
        let env = |key: &str| if key == "PATH" { Some(cli_path::search_path()) } else { std::env::var_os(key) };
        cli_path::resolve_with_retry(
            || resolve_executable(&env, cli_path::chosen(Cli::Codex).as_deref()),
            |error| error.kind == Kind::NotInstalled,
        )
    }

    fn launch(&self) -> Result<Spawned, CodexError> {
        let executable = self.resolve()?;
        if is_launcher_script(&executable) {
            return Err(err(Kind::PathInvalid));
        }
        let cwd = create_workspace()?;
        let Some(cwd_text) = cwd.to_str().map(str::to_string) else {
            let _ = std::fs::remove_dir(&cwd);
            return Err(err(Kind::StartFailed));
        };
        let mut command = Command::new(&executable);
        command
            .args(launch_arguments())
            .current_dir(&cwd)
            .env_clear()
            .envs(sanitize_environment(cli_path::with_search_path(std::env::vars_os())))
            .stdin(Stdio::piped())
            .stdout(Stdio::piped())
            // Diagnostics may contain private context; they are discarded, never logged.
            .stderr(Stdio::null());
        #[cfg(windows)]
        {
            use std::os::windows::process::CommandExt;
            const CREATE_NO_WINDOW: u32 = 0x0800_0000;
            command.creation_flags(CREATE_NO_WINDOW);
        }
        let mut child = match command.spawn() {
            Ok(child) => child,
            Err(error) => {
                let _ = std::fs::remove_dir(&cwd);
                return Err(err(if error.kind() == ErrorKind::NotFound { Kind::NotInstalled } else { Kind::StartFailed }));
            }
        };
        let (Some(stdin), Some(stdout)) = (child.stdin.take(), child.stdout.take()) else {
            let _ = child.kill();
            let _ = child.wait();
            let _ = std::fs::remove_dir(&cwd);
            return Err(err(Kind::StartFailed));
        };
        Ok(Spawned { writer: Box::new(stdin), reader: Box::new(stdout), process: Box::new(ChildProcess { child, cwd }), cwd: cwd_text })
    }

    fn open_url(&self, url: &str) -> Result<(), CodexError> {
        if !valid_auth_url(url) {
            return Err(err(Kind::LoginFailed));
        }
        let failed = || CodexError::new(Kind::LoginFailed, "Could not open the browser for sign-in.");
        #[cfg(windows)]
        let mut command = {
            let root = std::env::var_os("SystemRoot").map_or_else(|| PathBuf::from("C:\\Windows"), PathBuf::from);
            let mut command = Command::new(root.join("System32").join("rundll32.exe"));
            command.arg("url.dll,FileProtocolHandler").arg(url);
            command
        };
        #[cfg(target_os = "macos")]
        let mut command = {
            let mut command = Command::new("/usr/bin/open");
            command.arg(url);
            command
        };
        #[cfg(all(unix, not(target_os = "macos")))]
        let mut command = {
            let mut command = Command::new("xdg-open");
            command.arg(url);
            command
        };
        let mut child = command.stdin(Stdio::null()).stdout(Stdio::null()).stderr(Stdio::null()).spawn().map_err(|_| failed())?;
        std::thread::spawn(move || {
            let _ = child.wait();
        });
        Ok(())
    }
}

// ---------------------------------------------------------------------------------------------
// Executable resolution (resolve.js)

fn target() -> Option<(&'static str, &'static str)> {
    Some(match (std::env::consts::OS, std::env::consts::ARCH) {
        ("windows", "x86_64") => ("x86_64-pc-windows-msvc", "codex-win32-x64"),
        ("windows", "aarch64") => ("aarch64-pc-windows-msvc", "codex-win32-arm64"),
        ("macos", "x86_64") => ("x86_64-apple-darwin", "codex-darwin-x64"),
        ("macos", "aarch64") => ("aarch64-apple-darwin", "codex-darwin-arm64"),
        ("linux", "x86_64") => ("x86_64-unknown-linux-musl", "codex-linux-x64"),
        ("linux", "aarch64") => ("aarch64-unknown-linux-musl", "codex-linux-arm64"),
        _ => return None,
    })
}

const BINARY: &str = if cfg!(windows) { "codex.exe" } else { "codex" };

fn is_file(path: &Path) -> bool {
    std::fs::metadata(path).is_ok_and(|meta| meta.is_file())
}

/// `realpath` without Windows verbatim prefixes.
fn real(path: &Path) -> PathBuf {
    let Ok(resolved) = std::fs::canonicalize(path) else { return path.to_path_buf() };
    let Some(text) = resolved.to_str() else { return resolved };
    if let Some(rest) = text.strip_prefix("\\\\?\\UNC\\") {
        return PathBuf::from(format!("\\\\{rest}"));
    }
    if let Some(rest) = text.strip_prefix("\\\\?\\")
        && is_drive_root(rest)
    {
        return PathBuf::from(rest);
    }
    resolved
}

fn extension(path: &Path) -> String {
    path.extension().and_then(|ext| ext.to_str()).unwrap_or("").to_ascii_lowercase()
}

/// The native binary inside an official npm package (`bin/` in recent releases, `codex/` before).
fn package_binary(package_root: &Path) -> Option<PathBuf> {
    let (triple, package) = target()?;
    let root = real(package_root);
    let mut roots = vec![root.clone(), root.join("node_modules").join("@openai").join(package)];
    if let Some(parent) = root.parent() {
        roots.insert(1, parent.join(package));
    }
    for candidate_root in roots {
        for directory in ["bin", "codex"] {
            let candidate = candidate_root.join("vendor").join(triple).join(directory).join(BINARY);
            if is_file(&candidate) {
                return Some(real(&candidate));
            }
        }
    }
    None
}

/// Relative `…@openai/codex/bin/codex.js` entries referenced by an npm/pnpm launcher.
fn shim_entries(text: &str) -> Vec<String> {
    let lower = text.to_ascii_lowercase();
    let mut entries = Vec::new();
    for marker in ["%~dp0", "%dp0%", "$basedir"] {
        for (index, _) in lower.match_indices(marker) {
            let mut start = index + marker.len();
            if text[start..].starts_with(['\\', '/']) {
                start += 1;
            }
            let end = text[start..].find(['"', '\'', '\r', '\n']).map_or(text.len(), |offset| start + offset);
            let segment = &lower[start..end];
            let found = segment.match_indices("@openai").find_map(|(at, _)| {
                let tail = segment[at + 7..].replace('/', "\\");
                tail.starts_with("\\codex\\bin\\codex.js").then_some(at + 7 + "\\codex\\bin\\codex.js".len())
            });
            if let Some(length) = found {
                let entry = &text[start..start + length];
                if !entry.contains(['%', '$', '`', '\0']) {
                    entries.push(entry.to_string());
                }
            }
        }
    }
    entries
}

fn resolve_candidate(file: &Path) -> Option<PathBuf> {
    if !is_file(file) {
        return None;
    }
    let ext = extension(file);
    if cfg!(windows) && ext == "exe" {
        return Some(real(file));
    }
    if file.file_name().and_then(|name| name.to_str()).is_some_and(|name| name.eq_ignore_ascii_case("codex.js")) {
        return package_binary(real(file).parent()?.parent()?);
    }
    #[cfg(unix)]
    if ext != "cmd" && ext != "ps1" {
        use std::os::unix::fs::PermissionsExt;
        let actual = real(file);
        if actual.ends_with("bin/codex.js") {
            return package_binary(actual.parent()?.parent()?);
        }
        return std::fs::metadata(&actual).is_ok_and(|meta| meta.permissions().mode() & 0o111 != 0).then_some(actual);
    }
    if !["cmd", "ps1", ""].contains(&ext.as_str()) {
        return None;
    }
    if std::fs::metadata(file).map_or(true, |meta| meta.len() > MAX_SHIM_BYTES) {
        return None;
    }
    let text = std::fs::read_to_string(file).ok()?;
    let basedir = file.parent()?;
    for entry in shim_entries(&text) {
        let relative: PathBuf = entry.split(['\\', '/']).collect();
        let script = basedir.join(relative);
        if is_file(&script)
            && let Some(binary) = script.parent().and_then(Path::parent).and_then(package_binary)
        {
            return Some(binary);
        }
    }
    for root in [basedir.join("node_modules").join("@openai").join("codex"), basedir.join("global").join("5").join("node_modules").join("@openai").join("codex")] {
        if is_file(&root.join("bin").join("codex.js"))
            && let Some(binary) = package_binary(&root)
        {
            return Some(binary);
        }
    }
    None
}

/// The location chosen in Settings when it is usable, then CODEX_PATH, then PATH (see
/// `cli_path::search_path`), then the official Windows installer location. Launcher scripts are
/// only followed to the native binary of the official npm package; they are never executed.
fn resolve_executable(env: &dyn Fn(&str) -> Option<OsString>, chosen: Option<&Path>) -> Result<PathBuf, CodexError> {
    target().ok_or_else(|| err(Kind::NotInstalled))?;
    if let Some(found) = chosen.and_then(located) {
        return Ok(found);
    }
    if let Some(supplied) = env("CODEX_PATH").filter(|value| !value.is_empty()) {
        let text = supplied.to_str().ok_or_else(|| err(Kind::PathInvalid))?;
        let path = Path::new(text);
        if text.contains(['\0', '\r', '\n']) || !path.is_absolute() {
            return Err(err(Kind::PathInvalid));
        }
        return located(path).ok_or_else(|| err(Kind::NotInstalled));
    }
    let accept = |candidate: &Path| resolve_candidate(candidate).filter(|path| !is_launcher_script(path));
    let names =
        if cfg!(windows) { cli_path::file_names("codex", &["exe", "cmd", "ps1", ""], env("PATHEXT").as_deref()) } else { vec!["codex".to_string()] };
    if let Some(found) = env("PATH").and_then(|path| cli_path::find_in(&path, &names, accept)) {
        return Ok(found);
    }
    if cfg!(windows) {
        let local = env("LOCALAPPDATA").map(PathBuf::from).or_else(dirs::data_local_dir);
        if let Some(local) = local.filter(|local| local.is_absolute()) {
            let installed = local.join("Programs").join("OpenAI").join("Codex").join("bin").join("codex.exe");
            if let Some(found) = resolve_candidate(&installed) {
                return Ok(found);
            }
        }
    }
    Err(err(Kind::NotInstalled))
}

/// The native binary for a location given in full (Settings, CODEX_PATH): absolute, and a native
/// binary or an official npm launcher, which is followed to its binary and never run.
fn located(path: &Path) -> Option<PathBuf> {
    path.is_absolute().then(|| resolve_candidate(path)).flatten().filter(|found| !is_launcher_script(found))
}

// ---------------------------------------------------------------------------------------------
// Connection: one app-server process generation

enum Event {
    Response(u64, Result<Value, CodexError>),
    Notification(String, Value),
    Closed(CodexError),
}

struct ConnState {
    alive: bool,
    failure: Option<CodexError>,
    pending: HashMap<u64, Sender<Event>>,
    subscribers: Vec<(u64, Sender<Event>)>,
    next_subscriber: u64,
}

struct Connection {
    writer: Mutex<Option<Box<dyn Write + Send>>>,
    process: Mutex<Box<dyn Process>>,
    state: Mutex<ConnState>,
    closed: Mutex<Option<Receiver<()>>>,
    next_id: AtomicU64,
    cwd: String,
    policy: OnceLock<InstructionPolicy>,
}

fn lock<T: ?Sized>(mutex: &Mutex<T>) -> MutexGuard<'_, T> {
    mutex.lock().unwrap_or_else(std::sync::PoisonError::into_inner)
}

/// Removes a subscriber when the waiting operation ends.
struct Subscription<'a> {
    connection: &'a Connection,
    id: u64,
}

impl Drop for Subscription<'_> {
    fn drop(&mut self) {
        lock(&self.connection.state).subscribers.retain(|(id, _)| *id != self.id);
    }
}

impl Connection {
    /// Starts the reader thread for a freshly spawned transport.
    fn start(spawned: Spawned) -> Arc<Self> {
        let (closed_tx, closed_rx) = mpsc::channel();
        let connection = Arc::new(Self {
            writer: Mutex::new(Some(spawned.writer)),
            process: Mutex::new(spawned.process),
            state: Mutex::new(ConnState { alive: true, failure: None, pending: HashMap::new(), subscribers: Vec::new(), next_subscriber: 0 }),
            closed: Mutex::new(Some(closed_rx)),
            next_id: AtomicU64::new(0),
            cwd: spawned.cwd,
            policy: OnceLock::new(),
        });
        let reader_connection = connection.clone();
        let mut reader = spawned.reader;
        let started = std::thread::Builder::new().name("codex-stdout".into()).spawn(move || {
            reader_connection.read_loop(&mut *reader);
            drop(closed_tx);
        });
        if started.is_err() {
            connection.fail(err(Kind::StartFailed));
            connection.on_end();
        }
        connection
    }

    fn usable(&self) -> bool {
        let state = lock(&self.state);
        state.alive && state.failure.is_none()
    }

    fn unusable_error(state: &ConnState) -> CodexError {
        state.failure.clone().unwrap_or_else(|| err(Kind::Disconnected))
    }

    fn subscribe(&self) -> Result<(Subscription<'_>, Sender<Event>, Receiver<Event>), CodexError> {
        let (tx, rx) = mpsc::channel();
        let mut state = lock(&self.state);
        if !state.alive || state.failure.is_some() {
            return Err(Self::unusable_error(&state));
        }
        state.next_subscriber += 1;
        let id = state.next_subscriber;
        state.subscribers.push((id, tx.clone()));
        drop(state);
        Ok((Subscription { connection: self, id }, tx, rx))
    }

    fn write(&self, bytes: &[u8]) -> Result<(), CodexError> {
        let result = {
            let mut writer = lock(&self.writer);
            match writer.as_mut() {
                Some(writer) => writer.write_all(bytes).and_then(|()| writer.flush()).map_err(|_| err(Kind::Disconnected)),
                None => Err(err(Kind::Disconnected)),
            }
        };
        if let Err(error) = &result {
            self.fail(error.clone());
        }
        result
    }

    /// Sends a request whose response is delivered to `reply` as `Event::Response`.
    fn send_request(&self, method: &str, params: Value, reply: Sender<Event>) -> Result<u64, CodexError> {
        if !CLIENT_METHODS.contains(&method) {
            return Err(err(Kind::Blocked));
        }
        let id = self.next_id.fetch_add(1, Ordering::Relaxed) + 1;
        let line = encode_line(&json!({ "id": id, "method": method, "params": params }))?;
        {
            let mut state = lock(&self.state);
            if !state.alive || state.failure.is_some() {
                return Err(Self::unusable_error(&state));
            }
            if state.pending.len() >= MAX_PENDING {
                return Err(err(Kind::Busy));
            }
            state.pending.insert(id, reply);
        }
        if let Err(error) = self.write(&line) {
            self.forget(id);
            return Err(error);
        }
        Ok(id)
    }

    fn forget(&self, id: u64) {
        lock(&self.state).pending.remove(&id);
    }

    fn call(&self, method: &str, params: Value, timeout: Duration) -> Result<Value, CodexError> {
        let (tx, rx) = mpsc::channel();
        let id = self.send_request(method, params, tx)?;
        let deadline = Instant::now() + timeout;
        loop {
            let remaining = deadline.saturating_duration_since(Instant::now());
            match rx.recv_timeout(remaining) {
                Ok(Event::Response(response, outcome)) if response == id => return outcome,
                Ok(Event::Closed(error)) => return Err(error),
                Ok(_) => {}
                Err(RecvTimeoutError::Timeout) => {
                    self.forget(id);
                    return Err(err(Kind::Timeout));
                }
                Err(RecvTimeoutError::Disconnected) => return Err(Self::unusable_error(&lock(&self.state))),
            }
        }
    }

    /// Fire-and-forget request (its response is discarded by the reader).
    fn send_detached(&self, method: &str, params: Value) {
        let (tx, _rx) = mpsc::channel();
        let _ = self.send_request(method, params, tx);
    }

    fn notify_initialized(&self) -> Result<(), CodexError> {
        self.write(&encode_line(&json!({ "method": "initialized", "params": {} }))?)
    }

    /// Records a failure, wakes every waiter and stops the process. Idempotent.
    fn fail(&self, failure: CodexError) {
        let (pending, subscribers) = {
            let mut state = lock(&self.state);
            if !state.alive || state.failure.is_some() {
                return;
            }
            state.failure = Some(failure.clone());
            (std::mem::take(&mut state.pending), std::mem::take(&mut state.subscribers))
        };
        for (_, sender) in pending.into_iter().chain(subscribers) {
            let _ = sender.send(Event::Closed(failure.clone()));
        }
        // Kill before taking the writer so a write blocked on a full pipe is released.
        lock(&self.process).kill();
        lock(&self.writer).take();
    }

    /// The transport closed: wake waiters, reap the process and remove its workspace.
    fn on_end(&self) {
        let (failure, pending, subscribers) = {
            let mut state = lock(&self.state);
            if !state.alive {
                return;
            }
            state.alive = false;
            let failure = state.failure.clone().unwrap_or_else(|| err(Kind::Disconnected));
            (failure, std::mem::take(&mut state.pending), std::mem::take(&mut state.subscribers))
        };
        for (_, sender) in pending.into_iter().chain(subscribers) {
            let _ = sender.send(Event::Closed(failure.clone()));
        }
        lock(&self.writer).take();
        let mut process = lock(&self.process);
        process.kill();
        process.wait();
        process.cleanup();
    }

    fn read_loop(&self, reader: &mut dyn Read) {
        let mut buffer = LineBuffer::default();
        let mut chunk = vec![0u8; 64 * 1024];
        while self.usable() {
            let read = match reader.read(&mut chunk) {
                Ok(0) => break,
                Ok(read) => read,
                Err(error) if error.kind() == ErrorKind::Interrupted => continue,
                Err(_) => break,
            };
            match buffer.feed(&chunk[..read], MAX_LINE_BYTES) {
                Ok(lines) => {
                    for line in lines {
                        if let Err(error) = self.dispatch(&line) {
                            self.fail(error);
                            break;
                        }
                    }
                }
                Err(error) => self.fail(error),
            }
        }
        self.on_end();
    }

    fn dispatch(&self, line: &[u8]) -> Result<(), CodexError> {
        match parse_line(line)? {
            None => {}
            Some(Incoming::Request { id, method }) => {
                // A failed write already failed the connection.
                let _ = self.write(&encode_line(&denial(&id, &method))?);
            }
            Some(Incoming::Notification { method, params }) => {
                if !FORWARDED_NOTIFICATIONS.contains(&method.as_str())
                    || (method == "item/completed"
                        && params.get("item").and_then(|item| item.get("type")).and_then(Value::as_str) != Some("agentMessage"))
                {
                    return Ok(());
                }
                let mut state = lock(&self.state);
                state.subscribers.retain(|(_, sender)| sender.send(Event::Notification(method.clone(), params.clone())).is_ok());
            }
            Some(Incoming::Response { id, outcome }) => {
                let Some(id) = id.as_u64() else { return Ok(()) };
                let sender = lock(&self.state).pending.remove(&id);
                if let Some(sender) = sender {
                    let _ = sender.send(Event::Response(id, outcome.map_err(|error| rpc_error(&error))));
                }
            }
        }
        Ok(())
    }
}

// ---------------------------------------------------------------------------------------------
// Client

#[derive(Clone, Copy)]
struct Limits {
    request: Duration,
    turn: Duration,
    login: Duration,
    shutdown: Duration,
    poll: Duration,
}

impl Default for Limits {
    fn default() -> Self {
        Self {
            request: Duration::from_secs(15),
            turn: Duration::from_secs(180),
            login: Duration::from_secs(180),
            shutdown: Duration::from_secs(2),
            poll: Duration::from_millis(100),
        }
    }
}

#[derive(Debug, PartialEq)]
enum Account {
    None,
    ChatGpt { email: Option<String>, plan: Option<String> },
    Other,
}

fn account_from_response(response: &Value) -> Account {
    let account = response.get("account").unwrap_or(&Value::Null);
    if account.is_null() {
        return Account::None;
    }
    if account.get("type").and_then(Value::as_str) != Some("chatgpt") {
        return Account::Other;
    }
    let field = |key: &str, max: usize| {
        account.get(key).and_then(Value::as_str).filter(|text| !text.trim().is_empty()).map(|text| text.trim().chars().take(max).collect())
    };
    Account::ChatGpt { email: field("email", 254), plan: field("planType", 64) }
}

/// A thread kept open across the turns of one Live session (see `CodexClient::stream_turn`).
/// It is bound to the app-server connection it was started on and is unsubscribed when dropped.
pub struct CodexThread {
    connection: Arc<Connection>,
    thread_id: String,
    system: String,
    /// Turns the server has accepted on this thread.
    turns: u32,
    /// Bytes of instructions added to its history since it started (`CodexClient::reinstruct`).
    added: usize,
}

impl CodexThread {
    pub fn id(&self) -> &str { &self.thread_id }
}

impl Drop for CodexThread {
    fn drop(&mut self) {
        if self.connection.usable() {
            self.connection.send_detached("thread/unsubscribe", json!({ "threadId": self.thread_id }));
        }
    }
}

/// The official Codex app-server, started on demand and restarted after failures.
pub struct CodexClient {
    launcher: Box<dyn Launcher>,
    current: Mutex<Option<Arc<Connection>>>,
    limits: Limits,
    /// Reasoning efforts each model advertises (from `model/list`), read once.
    catalog: Mutex<Option<Catalog>>,
}

/// What `model/list` says about reasoning: the default model and each model's efforts.
#[derive(Clone, Debug, Default)]
struct Catalog {
    default_model: Option<String>,
    efforts: HashMap<String, Vec<String>>,
}

/// The model and reasoning effort a turn runs with.
#[derive(Clone, Copy)]
struct ModelChoice<'a> {
    /// `None` keeps the account's default model.
    model: Option<&'a str>,
    effort: &'static str,
}

/// Reasoning efforts from least to most thinking, as the app-server names them.
const EFFORT_ORDER: [&str; 8] = ["none", "minimal", "low", "medium", "high", "xhigh", "max", "ultra"];

/// The reasoning effort a turn asks for. Normal answers take the least the model offers, so the
/// first words arrive quickly (the user's own Codex config may ask for far more, which suits
/// coding but not live answers); Smart mode takes `high`, or the nearest level the model has.
fn pick_effort(supported: &[String], effort: Effort) -> &'static str {
    let rank = |level: &str| EFFORT_ORDER.iter().position(|known| *known == level);
    let mut known: Vec<usize> = supported.iter().filter_map(|level| rank(level)).collect();
    known.sort_unstable();
    let high = rank("high").expect("high is a known level");
    let chosen = match effort {
        Effort::Fast => known.first().copied(),
        Effort::Smart => known.iter().rev().find(|level| **level <= high).or(known.first()).copied(),
    };
    // Every current model takes low and high; they are the safe defaults when nothing is known.
    EFFORT_ORDER[chosen.unwrap_or(match effort { Effort::Fast => rank("low").expect("known"), Effort::Smart => high })]
}

impl CodexClient {
    pub fn new() -> Arc<Self> {
        Arc::new(Self::with_launcher(Box::new(SystemLauncher), Limits::default()))
    }

    fn with_launcher(launcher: Box<dyn Launcher>, limits: Limits) -> Self {
        Self { launcher, current: Mutex::new(None), limits, catalog: Mutex::new(None) }
    }

    /// Starts the app-server if needed and reads account state. Never panics; errors go in `error`.
    pub fn status(&self) -> SubscriptionStatus {
        let mut status = SubscriptionStatus::default();
        let path = match self.launcher.resolve() {
            Ok(path) => path,
            Err(error) => {
                status.error = Some(error.message);
                return status;
            }
        };
        status.installed = true;
        status.custom_location = cli_path::chosen(Cli::Codex).and_then(|chosen| located(&chosen)).is_some_and(|chosen| chosen == path);
        let result = self.connection().and_then(|connection| Ok((self.read_account(&connection)?, connection)));
        match result {
            Err(error) => status.error = Some(error.message),
            Ok((Account::ChatGpt { email, plan }, connection)) => {
                status.signed_in = true;
                status.account = email;
                status.plan = plan;
                status.models = self.models(&connection).unwrap_or_default();
                status.default_model = self.catalog.lock().unwrap_or_else(std::sync::PoisonError::into_inner).as_ref().and_then(|catalog| catalog.default_model.clone());
            }
            Ok((Account::Other, _)) => status.error = Some(err(Kind::AuthUnsupported).message),
            Ok((Account::None, _)) => {}
        }
        status
    }

    /// Starts ChatGPT sign-in in the browser and blocks until it completes or times out.
    pub fn login(&self) -> Result<(), String> {
        self.login_inner().map_err(|error| error.message)
    }

    pub fn logout(&self) -> Result<(), String> {
        let connection = self.connection().map_err(|error| error.message)?;
        connection.call("account/logout", json!({}), self.limits.request).map_err(|error| error.message)?;
        self.shutdown();
        Ok(())
    }

    /// One answer on a fresh ephemeral thread (stateless: history comes in `req.messages`).
    pub fn stream(&self, req: &ChatRequest, cancel: &AtomicBool, on_delta: &mut dyn FnMut(&str)) -> Result<String, String> {
        self.stream_inner(req, cancel, on_delta).map_err(|error| error.message)
    }

    pub fn shutdown(&self) {
        let Some(connection) = lock(&self.current).take() else { return };
        let closed = lock(&connection.closed).take();
        connection.fail(err(Kind::Cancelled));
        if let Some(closed) = closed {
            let _ = closed.recv_timeout(self.limits.shutdown);
        }
    }

    fn connection(&self) -> Result<Arc<Connection>, CodexError> {
        let mut current = lock(&self.current);
        if let Some(connection) = current.as_ref() {
            if connection.usable() {
                return Ok(connection.clone());
            }
            connection.fail(err(Kind::Disconnected));
        }
        *current = None;
        let connection = Connection::start(self.launcher.launch()?);
        match self.initialize(&connection) {
            Ok(()) => {
                *current = Some(connection.clone());
                Ok(connection)
            }
            Err(error) => {
                let error = if error.kind == Kind::Disconnected { err(Kind::StartFailed) } else { error };
                connection.fail(error.clone());
                Err(error)
            }
        }
    }

    fn initialize(&self, connection: &Connection) -> Result<(), CodexError> {
        let params = json!({
            "clientInfo": { "name": "cluelyrs_private_assistant", "title": "Private Assistant", "version": env!("CARGO_PKG_VERSION") },
            "capabilities": { "experimentalApi": false, "requestAttestation": false },
        });
        let initialized = connection.call("initialize", params, self.limits.request)?;
        let _ = connection.policy.set(InstructionPolicy::from_initialize(&initialized));
        connection.notify_initialized()
    }

    fn read_account(&self, connection: &Connection) -> Result<Account, CodexError> {
        let response = connection.call("account/read", json!({ "refreshToken": false }), self.limits.request)?;
        Ok(account_from_response(&response))
    }

    fn require_chatgpt(&self, connection: &Connection) -> Result<(), CodexError> {
        match self.read_account(connection)? {
            Account::ChatGpt { .. } => Ok(()),
            Account::Other => Err(err(Kind::AuthUnsupported)),
            Account::None => Err(err(Kind::AuthRequired)),
        }
    }

    fn models(&self, connection: &Connection) -> Result<Vec<(String, String)>, CodexError> {
        let mut models = Vec::new();
        let mut catalog = Catalog::default();
        let mut cursor: Option<String> = None;
        'pages: for _ in 0..10 {
            let mut params = json!({ "includeHidden": false });
            if let Some(cursor) = &cursor {
                params["cursor"] = json!(cursor);
            }
            let response = connection.call("model/list", params, self.limits.request)?;
            for model in response.get("data").and_then(Value::as_array).into_iter().flatten() {
                let Some(id) = model.get("id").and_then(Value::as_str).filter(|id| valid_model(id)) else { continue };
                if model.get("hidden") == Some(&Value::Bool(true)) || models.iter().any(|(known, _)| known == id) {
                    continue;
                }
                let efforts = model.get("supportedReasoningEfforts").and_then(Value::as_array).into_iter().flatten()
                    .filter_map(|option| option.get("reasoningEffort").and_then(Value::as_str))
                    .filter(|level| EFFORT_ORDER.contains(level)).map(str::to_string).collect();
                catalog.efforts.insert(id.to_string(), efforts);
                if model.get("isDefault") == Some(&Value::Bool(true)) { catalog.default_model = Some(id.to_string()); }
                let name = model.get("displayName").and_then(Value::as_str).map(str::trim).filter(|name| !name.is_empty()).unwrap_or(id);
                models.push((id.to_string(), name.chars().take(80).collect()));
                if models.len() >= MAX_MODELS {
                    break 'pages;
                }
            }
            cursor = response.get("nextCursor").and_then(Value::as_str).filter(|cursor| !cursor.is_empty()).map(str::to_string);
            if cursor.is_none() {
                break;
            }
        }
        *self.catalog.lock().unwrap_or_else(std::sync::PoisonError::into_inner) = Some(catalog);
        Ok(models)
    }

    /// The reasoning effort for a turn of `model` (`None`: the account's default model). The
    /// model list is read once per client (it costs no usage); without it, `pick_effort`
    /// falls back to levels every current model accepts.
    fn effort_for(&self, connection: &Connection, model: Option<&str>, effort: Effort) -> &'static str {
        let known = self.catalog.lock().unwrap_or_else(std::sync::PoisonError::into_inner).clone();
        let catalog = match known {
            Some(catalog) => catalog,
            None => { let _ = self.models(connection); self.catalog.lock().unwrap_or_else(std::sync::PoisonError::into_inner).clone().unwrap_or_default() }
        };
        let id = model.map(str::to_string).or(catalog.default_model.clone()).unwrap_or_default();
        pick_effort(catalog.efforts.get(&id).map(Vec::as_slice).unwrap_or(&[]), effort)
    }

    fn login_inner(&self) -> Result<(), CodexError> {
        let connection = self.connection()?;
        // Subscribe first so a fast completion is never missed.
        let (_subscription, tx, rx) = connection.subscribe()?;
        let start = connection.send_request("account/login/start", json!({ "type": "chatgpt" }), tx)?;
        let deadline = Instant::now() + self.limits.request;
        let mut early_completions = Vec::new();
        let response = loop {
            match rx.recv_timeout(deadline.saturating_duration_since(Instant::now())) {
                Ok(Event::Response(id, outcome)) if id == start => break outcome?,
                Ok(Event::Notification(method, params)) if method == "account/login/completed" => early_completions.push(params),
                Ok(Event::Closed(error)) => return Err(error),
                Ok(_) => {}
                Err(_) => {
                    connection.forget(start);
                    return Err(err(Kind::Timeout));
                }
            }
        };
        let unsupported = || CodexError::new(Kind::LoginFailed, "Codex returned an unsupported sign-in flow.");
        let login_id = response.get("loginId").and_then(Value::as_str).filter(|id| !id.is_empty() && id.len() <= 256).ok_or_else(unsupported)?;
        let url = response.get("authUrl").and_then(Value::as_str).ok_or_else(unsupported)?;
        if response.get("type").and_then(Value::as_str) != Some("chatgpt") || !valid_auth_url(url) {
            return Err(unsupported());
        }
        let cancel_login = || connection.send_detached("account/login/cancel", json!({ "loginId": login_id }));
        if let Err(error) = self.launcher.open_url(url) {
            cancel_login();
            return Err(error);
        }
        let completion = |params: &Value| -> Option<Result<(), CodexError>> {
            let id = params.get("loginId");
            if !(id.is_none_or(Value::is_null) || id.and_then(Value::as_str) == Some(login_id)) {
                return None;
            }
            Some(if params.get("success") == Some(&Value::Bool(true)) { Ok(()) } else { Err(err(Kind::LoginFailed)) })
        };
        if let Some(result) = early_completions.iter().find_map(completion) {
            return result;
        }
        let deadline = Instant::now() + self.limits.login;
        loop {
            match rx.recv_timeout(deadline.saturating_duration_since(Instant::now())) {
                Ok(Event::Notification(method, params)) if method == "account/login/completed" => {
                    if let Some(result) = completion(&params) {
                        return result;
                    }
                }
                Ok(Event::Closed(error)) => return Err(error),
                Ok(_) => {}
                Err(_) => {
                    cancel_login();
                    return Err(CodexError::new(Kind::Timeout, "Sign-in timed out. Try again."));
                }
            }
        }
    }

    fn stream_inner(&self, req: &ChatRequest, cancel: &AtomicBool, on_delta: &mut dyn FnMut(&str)) -> Result<String, CodexError> {
        if cancel.load(Ordering::Relaxed) {
            return Err(err(Kind::Cancelled));
        }
        let input = fold_input(&req.messages)?;
        let model = req.model.as_deref().map(str::trim).filter(|model| !model.is_empty());
        if model.is_some_and(|model| !valid_model(model)) {
            return Err(CodexError::new(Kind::InputInvalid, "Choose a valid Codex model in Settings."));
        }
        if req.system.len() > MAX_INSTRUCTIONS {
            return Err(err(Kind::RequestTooLarge));
        }
        let connection = self.connection()?;
        self.require_chatgpt(&connection)?;
        if cancel.load(Ordering::Relaxed) {
            return Err(err(Kind::Cancelled));
        }
        let thread_id = self.start_thread(&connection, &req.system)?;
        let effort = self.effort_for(&connection, model, req.effort);
        let result = self.run_turn(&connection, &thread_id, input, ModelChoice { model, effort }, cancel, on_delta);
        if connection.usable() {
            connection.send_detached("thread/unsubscribe", json!({ "threadId": thread_id }));
        }
        result
    }

    /// Starts a restricted, ephemeral thread and returns its id. The effective config is
    /// refreshed before every thread; the server's reply is checked for every restriction.
    fn start_thread(&self, connection: &Arc<Connection>, system: &str) -> Result<String, CodexError> {
        let effective = connection.call("config/read", json!({ "includeLayers": false, "cwd": connection.cwd }), self.limits.request)?;
        let config = thread_config_from_effective(effective.get("config"))?;
        let started = connection.call(
            "thread/start",
            json!({
                "baseInstructions": system, "developerInstructions": "", "ephemeral": true, "cwd": connection.cwd,
                "modelProvider": "openai", "approvalPolicy": "never", "sandbox": "read-only", "config": config,
            }),
            self.limits.request,
        )?;
        match validate_thread_start(&started, &connection.cwd, connection.policy.get()) {
            Ok(thread_id) => Ok(thread_id),
            Err(error) => {
                connection.fail(error.clone());
                Err(error)
            }
        }
    }

    /// One turn on a thread kept open across requests (a Live session). The thread carries the
    /// conversation server-side, so only the last message of `req.messages` is sent, also after
    /// the instructions change (they are added to the thread; see `CodexClient::open_thread`).
    /// When the app-server has been restarted since the thread opened (or no thread is open
    /// yet), a new thread is started with the same restrictions and the whole `req.messages`
    /// history is folded into its first turn. Cancellation interrupts the turn; the thread stays usable.
    pub fn stream_turn(&self, thread: &mut Option<CodexThread>, req: &ChatRequest, cancel: &AtomicBool, on_delta: &mut dyn FnMut(&str)) -> Result<String, String> {
        self.stream_turn_inner(thread, req, cancel, on_delta).map_err(|error| error.message)
    }

    /// Free preparation for a Live session: start the app-server, read the model list and open
    /// the session's restricted thread now, so the first answer pays only for its turn. Opening
    /// a thread runs no model turn and costs no usage. Does nothing if a usable thread with the
    /// same instructions is already open. One with other instructions that already holds turns
    /// is kept as it is: the next turn adds the instructions it runs under (see
    /// `CodexClient::open_thread`), so edits to the active mode between answers add nothing.
    pub fn prepare_thread(&self, thread: &mut Option<CodexThread>, system: &str) -> Result<(), String> {
        let mut prepare = || -> Result<(), CodexError> {
            if system.len() > MAX_INSTRUCTIONS {
                return Err(err(Kind::RequestTooLarge));
            }
            let connection = self.connection()?;
            self.require_chatgpt(&connection)?;
            if self.catalog.lock().unwrap_or_else(std::sync::PoisonError::into_inner).is_none() {
                let _ = self.models(&connection);
            }
            self.open_thread(&connection, thread, system, false)
        };
        prepare().map_err(|error| error.message)
    }

    /// Makes `thread` a usable thread on `connection` running under `system`. An open thread
    /// with those instructions is kept. One that already holds turns under other instructions
    /// (the user switched modes mid-session) is kept too, with the new instructions added to
    /// its history, so the next answer still has every earlier turn, screenshots included.
    /// They are added only `for_turn`, just before the turn that runs under them: the active
    /// mode is applied again on every saved edit, and adding each version would leave every
    /// copy in the thread. Otherwise (no thread, a restarted server, nothing to keep, an
    /// app-server that can't add the instructions, or more added to this thread than
    /// `MAX_ADDED_INSTRUCTIONS`) a new thread is started; its first turn folds in the history.
    fn open_thread(&self, connection: &Arc<Connection>, thread: &mut Option<CodexThread>, system: &str, for_turn: bool) -> Result<(), CodexError> {
        if let Some(open) = thread.as_mut().filter(|open| Arc::ptr_eq(&open.connection, connection)) {
            if open.system == system { return Ok(()); }
            if open.turns > 0 && open.added + system.len() <= MAX_ADDED_INSTRUCTIONS {
                if !for_turn { return Ok(()); }
                match self.reinstruct(connection, open, system) {
                    Ok(()) => return Ok(()),
                    Err(error) => eprintln!("codex: the new instructions start a new thread: {}", error.message),
                }
            }
        }
        *thread = None;
        let thread_id = self.start_thread(connection, system)?;
        *thread = Some(CodexThread { connection: connection.clone(), thread_id, system: system.to_string(), turns: 0, added: 0 });
        Ok(())
    }

    /// Adds `system` to the thread's history as a developer message, without running a turn.
    /// The thread's base instructions can't be changed once it has started, and ephemeral
    /// threads can't be forked or resumed with new ones, so the message says it replaces them.
    fn reinstruct(&self, connection: &Connection, open: &mut CodexThread, system: &str) -> Result<(), CodexError> {
        let text = format!("{NEW_INSTRUCTIONS}\n\n{system}");
        let message = json!({ "type": "message", "role": "developer", "content": [{ "type": "input_text", "text": text }] });
        connection.call("thread/inject_items", json!({ "threadId": open.thread_id, "items": [message] }), self.limits.request)?;
        open.system = system.to_string();
        open.added += system.len();
        Ok(())
    }

    fn stream_turn_inner(&self, thread: &mut Option<CodexThread>, req: &ChatRequest, cancel: &AtomicBool, on_delta: &mut dyn FnMut(&str)) -> Result<String, CodexError> {
        if cancel.load(Ordering::Relaxed) {
            return Err(err(Kind::Cancelled));
        }
        let model = req.model.as_deref().map(str::trim).filter(|model| !model.is_empty());
        if model.is_some_and(|model| !valid_model(model)) {
            return Err(CodexError::new(Kind::InputInvalid, "Choose a valid Codex model in Settings."));
        }
        if req.system.len() > MAX_INSTRUCTIONS {
            return Err(err(Kind::RequestTooLarge));
        }
        let connection = self.connection()?;
        self.require_chatgpt(&connection)?;
        if cancel.load(Ordering::Relaxed) {
            return Err(err(Kind::Cancelled));
        }
        self.open_thread(&connection, thread, &req.system, true)?;
        let open = thread.as_mut().expect("thread was just opened");
        // A reused thread already holds the earlier exchanges; only the new message goes in.
        let messages = if open.turns > 0 { &req.messages[req.messages.len().saturating_sub(1)..] } else { &req.messages[..] };
        let input = fold_input(messages)?;
        let effort = self.effort_for(&connection, model, req.effort);
        let result = self.run_turn(&connection, &open.thread_id, input, ModelChoice { model, effort }, cancel, on_delta);
        match &result {
            Ok(_) => open.turns += 1,
            // The server never heard the message (or the connection is gone); don't count on it.
            Err(_) if !connection.usable() => *thread = None,
            Err(_) => {}
        }
        result
    }

    fn run_turn(
        &self,
        connection: &Connection,
        thread_id: &str,
        input: Vec<Value>,
        choice: ModelChoice,
        cancel: &AtomicBool,
        on_delta: &mut dyn FnMut(&str),
    ) -> Result<String, CodexError> {
        let (_subscription, tx, rx) = connection.subscribe()?;
        let mut params = json!({
            "threadId": thread_id, "input": input, "cwd": connection.cwd, "approvalPolicy": "never",
            "sandboxPolicy": { "type": "readOnly", "networkAccess": false },
            // Overrides the reasoning inherited from the user's own Codex config for this turn;
            // summaries are never shown, so none are generated.
            "effort": choice.effort, "summary": "none",
        });
        if let Some(model) = choice.model {
            params["model"] = json!(model);
        }
        let start = connection.send_request("turn/start", params, tx)?;
        let started_at = Instant::now();
        let mut tracker = TurnTracker::new(thread_id);
        let mut emit = |delta: &str| {
            if !cancel.load(Ordering::Relaxed) {
                on_delta(delta);
            }
        };
        loop {
            if cancel.load(Ordering::Relaxed) {
                // Cancelled before the server acknowledged the turn (a speculative answer replaced
                // by a newer line): wait for the acknowledgement so the turn can be interrupted by
                // id, rather than stopping the app-server and the session's warm thread with it.
                if tracker.turn_id.is_none() && !tracker.finished { self.await_acknowledgement(&rx, start, started_at, &mut tracker); }
                return Err(self.abort_turn(connection, &tracker, start, err(Kind::Cancelled)));
            }
            let elapsed = started_at.elapsed();
            if elapsed >= self.limits.turn {
                return Err(self.abort_turn(connection, &tracker, start, CodexError::new(Kind::Timeout, "Codex took too long to finish. Please retry.")));
            }
            if tracker.turn_id.is_none() && elapsed >= self.limits.request {
                return Err(self.abort_turn(connection, &tracker, start, err(Kind::Timeout)));
            }
            let step = match rx.recv_timeout(self.limits.poll) {
                Ok(Event::Response(id, outcome)) if id == start => tracker.on_started(&outcome?, &mut emit),
                Ok(Event::Notification(method, params)) => tracker.on_notification(&method, &params, &mut emit),
                Ok(Event::Closed(error)) => return Err(if error.kind == Kind::Cancelled { error } else { err(Kind::Disconnected) }),
                Ok(Event::Response(..)) | Err(RecvTimeoutError::Timeout) => Ok(TurnStep::Continue),
                Err(RecvTimeoutError::Disconnected) => return Err(err(Kind::Disconnected)),
            };
            match step {
                Ok(TurnStep::Done(text)) => return Ok(text),
                Ok(TurnStep::Continue) => {}
                Err(error) => return Err(self.abort_turn(connection, &tracker, start, error)),
            }
        }
    }

    /// Reads the turn's events, showing nothing, until the server acknowledges it, the turn
    /// ends, or the request limit since it was sent passes.
    fn await_acknowledgement(&self, rx: &Receiver<Event>, start: u64, started_at: Instant, tracker: &mut TurnTracker) {
        let mut hidden = |_: &str| {};
        while tracker.turn_id.is_none() && !tracker.finished {
            let Some(left) = self.limits.request.checked_sub(started_at.elapsed()) else { return };
            match rx.recv_timeout(left.min(self.limits.poll)) {
                Ok(Event::Response(id, outcome)) if id == start => match outcome {
                    Ok(result) => { if tracker.on_started(&result, &mut hidden).is_err() { return; } }
                    Err(_) => return,
                },
                Ok(Event::Notification(method, params)) => { if tracker.on_notification(&method, &params, &mut hidden).is_err() { return; } }
                Ok(Event::Closed(_)) | Err(RecvTimeoutError::Disconnected) => return,
                Ok(Event::Response(..)) | Err(RecvTimeoutError::Timeout) => {}
            }
        }
    }

    /// Stops an unfinished turn. An unacknowledged or uninterruptible turn may still be running,
    /// so the process is stopped instead of being reused.
    fn abort_turn(&self, connection: &Connection, tracker: &TurnTracker, start: u64, error: CodexError) -> CodexError {
        if tracker.finished {
            return error;
        }
        match &tracker.turn_id {
            Some(turn_id) => {
                let interrupted = connection.call("turn/interrupt", json!({ "threadId": tracker.thread_id, "turnId": turn_id }), self.limits.request);
                if interrupted.is_err() {
                    connection.fail(err(Kind::Disconnected));
                }
            }
            None => {
                connection.forget(start);
                connection.fail(error.clone());
            }
        }
        error
    }
}

impl Drop for CodexClient {
    fn drop(&mut self) {
        self.shutdown();
    }
}

