    fn windows_policy() -> InstructionPolicy {
        InstructionPolicy::from_initialize(&json!({ "codexHome": "C:\\Users\\Me\\.codex", "platformFamily": "windows" }))
    }

    #[test]
    fn instruction_policy_accepts_one_global_source() {
        let policy = windows_policy();
        for ok in [json!([]), json!(["C:\\Users\\Me\\.codex\\AGENTS.md"]), json!(["\\\\?\\c:\\users\\me\\.codex\\agents.override.md"]), json!(["C:/Users/Me/.codex/AGENTS.md"])] {
            assert!(policy.allows(Some(&ok)), "{ok}");
        }
        for bad in [
            json!(["C:\\project\\AGENTS.md"]),
            json!(["C:\\Users\\Me\\.codex\\AGENTS.md", "C:\\Users\\Me\\.codex\\AGENTS.override.md"]),
            json!(["C:\\Users\\Me\\.codex\\sub\\..\\AGENTS.md"]),
            json!(["\\\\.\\C:\\Users\\Me\\.codex\\AGENTS.md"]),
            json!(["AGENTS.md"]),
            json!(["C:\\Users\\Me\\.codex\\notes.md"]),
            json!([1]),
            json!("C:\\Users\\Me\\.codex\\AGENTS.md"),
        ] {
            assert!(!policy.allows(Some(&bad)), "{bad}");
        }
        assert!(!policy.allows(None));
        let unix = InstructionPolicy::from_initialize(&json!({ "codexHome": "/home/me/.codex/", "platformFamily": "unix" }));
        assert!(unix.allows(Some(&json!(["/home/me/.codex/AGENTS.md"]))));
        assert!(!unix.allows(Some(&json!(["/home/me/.codex/../AGENTS.md"]))));
        assert!(!unix.allows(Some(&json!(["/home/me/project/AGENTS.md"]))));
        let unknown = InstructionPolicy::from_initialize(&json!({ "codexHome": "/x", "platformFamily": "plan9" }));
        assert!(unknown.allows(Some(&json!([]))) && !unknown.allows(Some(&json!(["/x/AGENTS.md"]))));
    }

