    #[test]
    fn errors_map_to_user_safe_messages() {
        assert_eq!(rpc_error(&json!({ "code": 429, "message": "" })).kind, Kind::UsageLimit);
        assert_eq!(rpc_error(&json!({ "code": -1, "message": "Rate-limit reached" })).kind, Kind::UsageLimit);
        assert_eq!(rpc_error(&json!({ "code": -1, "message": "You exceeded your quota" })).kind, Kind::UsageLimit);
        assert_eq!(rpc_error(&json!({ "code": 401 })).kind, Kind::AuthRequired);
        assert_eq!(rpc_error(&json!({ "message": "Not authenticated, see https://auth.openai.com/x" })).kind, Kind::AuthRequired);
        let generic = rpc_error(&json!({ "code": -32000, "message": "failed at C:\\Users\\me\\secret.toml" }));
        assert_eq!(generic.kind, Kind::RequestFailed);
        assert!(!generic.message.contains("C:\\"));
        let turn = |info: Value, message: &str| turn_failure(&json!({ "status": "failed", "error": { "message": message, "codexErrorInfo": info } })).kind;
        assert_eq!(turn(json!("usageLimitExceeded"), ""), Kind::UsageLimit);
        assert_eq!(turn(json!("unauthorized"), ""), Kind::AuthRequired);
        assert_eq!(turn(json!({ "httpConnectionFailed": { "httpStatusCode": null } }), ""), Kind::Network);
        assert_eq!(turn(Value::Null, "stream disconnected: network"), Kind::Network);
        assert_eq!(turn(Value::Null, "model error"), Kind::TurnFailed);
        assert_eq!(turn_failure(&json!({ "status": "interrupted" })).kind, Kind::Cancelled);
        assert!(err(Kind::NotInstalled).message.starts_with("Install the Codex CLI"));
    }

